def goal_finder(lang='de',base=''):
 keys=['marketing','technology','ai','consulting']
 L=GOAL_TRANSLATIONS.get(lang,dict(kicker='IHR ZIEL IST DER AUSGANGSPUNKT',title='Was möchten Sie<br>voranbringen?',intro='Wählen Sie Ihr Anliegen. Wir zeigen Ihnen einen passenden Einstieg in die Zusammenarbeit.',labels=[TOPICS[k]['label'] for k in keys],cta='Projekt besprechen',details='Leistung kennenlernen',next='Ihr möglicher Einstieg',titles=[TOPICS[k]['title'] for k in keys],texts=[TOPICS[k]['text'] for k in keys]))
 buttons=''.join(f'<button type="button" data-goal-choice="{key}" aria-pressed="{str(i==0).lower()}" aria-controls="goal-{key}"><span>0{i+1}</span>{e(L["labels"][i])}<b aria-hidden="true">↗</b></button>' for i,key in enumerate(keys))
 panels=''
 for i,key in enumerate(keys):
  T=TOPICS[key]
  panels+=f'<div class="goal-result" id="goal-{key}" data-goal-panel="{key}"{(" hidden" if i else "")}><div class="goal-result-copy"><p class="v-kicker">{L["next"]}</p><h3>{e(L["titles"][i])}</h3><p>{e(L["texts"][i])}</p><div class="goal-result-actions"><a class="btn btn-1" href="{base}kontakt.html?thema={key}#projektanfrage">{L["cta"]} ↗</a><a class="goal-details" href="{base}{T["href"]}">{L["details"]} →</a></div></div><div class="goal-result-image">{image(T["image"],T["case"],base)}<span>{e(T["case"]) if lang=="de" else ["A&B Bau","Tafolli Boost","Tafolli Boost","Restaurant Wochenmarkt"][i]}</span></div></div>'
 return f'<section class="goal-finder" data-goal-finder id="ihr-ziel"><div class="shell"><div class="visual-section-heading"><div><p class="v-kicker">{L["kicker"]}</p><h2>{L["title"]}</h2></div><p>{L["intro"]}</p></div><div class="goal-layout"><div class="goal-options" role="group" aria-label="{e(L["kicker"])}">{buttons}</div><div class="goal-panels">{panels}</div></div></div></section>'


def bridge(kind='technology'):
 T=TOPICS[kind]
 return f'<div class="case-conversion"><div><p class="v-kicker">IHR PROJEKT KÖNNTE DAS NÄCHSTE SEIN.</p><h3>Was möchten Sie bei sich verändern?</h3><p>Erzählen Sie uns von Ihrer Aufgabe. Gemeinsam klären wir, welche Lösung zu Ihrem Unternehmen passt.</p></div><a class="btn btn-1" href="kontakt.html?thema={kind}#projektanfrage">{e(T["cta"])} ↗</a></div>'


def brief():
 opts=''.join(f'<option value="{k}">{e(t["label"])}</option>' for k,t in TOPICS.items())
 return f'''<section class="project-brief-section" id="projektanfrage"><div class="shell project-brief-grid"><div><p class="v-kicker">LASSEN SIE UNS KONKRET WERDEN.</p><h2>Ihre Aufgabe.<br>Unser nächstes Gespräch.</h2><p>Ein paar Sätze reichen für den Anfang. Ob neue Idee oder bestehendes Projekt: Beschreiben Sie, was Sie erreichen möchten.</p><ol class="brief-next"><li><span>01</span><div><strong>Sie erzählen von Ihrem Vorhaben.</strong><p>Ziel, Ausgangslage und offene Fragen.</p></div></li><li><span>02</span><div><strong>Wir klären den passenden Einstieg.</strong><p>Was gebraucht wird und wie wir vorgehen.</p></div></li><li><span>03</span><div><strong>Sie erhalten ein konkretes Angebot.</strong><p>Mit Leistungsumfang und abgestimmten Kosten.</p></div></li></ol><a class="brief-direct" href="tel:+4917664616146">Lieber direkt sprechen? +49 176 64616146 ↗</a></div><form class="project-brief" data-project-brief action="{ACTION}" data-delivery-endpoint="{ENDPOINT}" method="post"><label for="brief-topic">Worum geht es?<select id="brief-topic" name="thema">{opts}<option value="offen">Das möchte ich gemeinsam herausfinden</option></select></label><div class="brief-contact-grid"><label for="brief-name">Ihr Name<input id="brief-name" name="name" autocomplete="name" required maxlength="120"></label><label for="brief-email">Ihre E-Mail-Adresse<input id="brief-email" name="email" type="email" autocomplete="email" required maxlength="254"></label></div><label for="brief-company">Unternehmen <span>(optional)</span><input id="brief-company" name="company" autocomplete="organization" maxlength="160"></label><label for="brief-message">Was möchten Sie erreichen?<textarea id="brief-message" name="message" rows="5" required minlength="15" maxlength="4000" placeholder="Zum Beispiel: Wir brauchen eine App für unsere Kunden und möchten unser bestehendes System anbinden."></textarea></label><label for="brief-timing">Wann soll es losgehen?<select id="brief-timing" name="zeitraum"><option>Zeitraum gemeinsam klären</option><option>Möglichst bald</option><option>In den nächsten 3 Monaten</option><option>Später – zunächst Orientierung</option></select></label><label class="brief-honey" aria-hidden="true">Website<input name="_honey" tabindex="-1" autocomplete="off"></label><input type="hidden" name="_subject" value="Tafolli &amp; Co. | Projektanfrage"><input type="hidden" name="_template" value="table"><input type="hidden" name="_url" value="https://tafolli.net/"><button class="btn btn-1" type="submit">Projektanfrage senden ↗</button><p class="brief-mail-note">Ihre Angaben werden erst beim Absenden über FormSubmit an info@tafolli.net übermittelt. Wir verwenden sie zur Bearbeitung Ihrer Anfrage. <a href="datenschutz.html#budgetplaner-datenschutz">Datenschutzhinweise</a>.</p><a class="brief-mail-fallback" data-brief-mailto href="mailto:info@tafolli.net">Alternativ im E-Mail-Programm senden ↗</a><p class="brief-form-status" data-brief-status role="status"></p><noscript><p>Schreiben Sie uns direkt an <a href="mailto:info@tafolli.net">info@tafolli.net</a>.</p></noscript></form></div></section>'''
